"""Lossless release/component evidence archive before generated cleanup."""
import gzip,json,subprocess
from run_core import ROOT
from archive_lossless_evidence import freeze,sha

def main():
 report=json.loads((ROOT/'analysis/playable_map_conversion_v0280_report.json').read_bytes())
 assert report['passed'] and report['md_sha256']==sha((ROOT/'gaw-megadrive.bin').read_bytes())
 for name in ['inventory_publication_v0280_report.json','title_cadence_v0280_report.json','title_cadence_v0280_pal_report.json']:
  r=json.loads((ROOT/'analysis'/name).read_bytes());assert r['md_sha256']==report['md_sha256']
 pixels=json.loads((ROOT/'analysis/md_source_room_budget_pixels_report.json').read_bytes());assert pixels['passed'] and pixels['native_images']==268
 for name,digest in pixels['module_sha256'].items():assert sha((ROOT/'megadrive/src'/name).read_bytes())==digest
 timing=json.loads((ROOT/'analysis/md_source_room_budget_current_report.json').read_bytes())
 assert timing['test_rom_sha256']==pixels['test_rom_sha256']
 prefix=json.loads((ROOT/'analysis/map_conversion_worklog_prefix.json').read_bytes());assert sha((ROOT/'analysis/world_next.md').read_bytes()[:prefix['bytes']])==prefix['sha256']
 protected=[ROOT/'input/original.sms',ROOT/'gaw-megadrive.bin',ROOT/'gaw-title-megadrive.bin',*sorted((ROOT/'versions').glob('*/*.bin'))]
 before={p.relative_to(ROOT).as_posix():sha(p.read_bytes()) for p in protected};assert len(list((ROOT/'versions').glob('*/*.bin')))==280
 roots=[ROOT/'validation'/name for name in ['map-conversion-v0276','md-source-room-budget-baseline','md-source-room-budget-current','md-source-room-budget-profile','sms-sprite8','sms-title-cadence','md-title-cadence','sms-title-cadence-pal','md-title-cadence-pal']]
 roots += sorted((ROOT/'validation').glob('menu-transition-*-auto-*'))+sorted((ROOT/'validation').glob('menu-transition-*-pal-*'))
 roots=[p for p in roots if p.is_dir()]
 paths=[p for folder in roots for p in folder.rglob('*') if p.is_file()]
 paths += [p for p in (ROOT/'megadrive/src').iterdir() if p.is_file()]
 paths += [ROOT/'build.ps1',ROOT/'README.md',ROOT/'analysis/world_next.md']
 paths += [ROOT/'tools'/n for n in ['validate_playable_map_conversion.py','validate_sms_sprite8_update.py','validate_sms_sprite8.py','validate_md_source_room_budget.py','profile_md_source_room_delta.py','profile_md_source_room_cost.py','archive_map_conversion_v0280.py','validate_native_patterns.py','validate_native_patterns_68k.py','profile_menu_transitions.py','validate_menu_transitions.py','validate_title_cadence.py']]
 paths += [ROOT/'analysis'/n for n in ['map_conversion_v0280.md','map_conversion_worklog_prefix.json','playable_map_conversion_v0280_report.json','inventory_publication_v0280_report.json','title_cadence_v0280_report.json','title_cadence_v0280_pal_report.json','md_source_room_budget_baseline_report.json','md_source_room_budget_current_report.json','md_source_room_budget_pixels_report.json','md_source_room_cost_report.json','sms_sprite8_report.json','sms_sprite8_update_report.json','native_patterns_report.json','class0_video_conversion_report.json','class0_video_68k_report.json']]
 paths += [ROOT/'validation'/n for n in ['menu_transition_profile.json','menu_transition_report.json','title_cadence_report.json','title_cadence-pal_report.json','build-v0276.log','build-v0277.log','build-v0278.log','build-v0279.log','build-v0280.log','sms-sprite8-current.log','sms-sprite8-update.log','md-source-room-budget-run.log']]
 out=ROOT/'analysis/map-conversion-v0280'
 m=freeze(ROOT,out,paths,dict(release=280,protected_sha256=before,purpose='Playable map conversion, IRQ-owned inventory publication and separate incremental room rendering',numbered_roms_preserved=280),roots,cleanup=True)
 # Generated fixture header is large; preserve its compressed object/readback.
 tracked=set(subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\0'))
 for path in [ROOT/'validation/md-source-room-budget-current/src/cases.h']:
  path=path.resolve();assert path.is_relative_to(ROOT/'validation/md-source-room-budget-current')
  name=path.relative_to(ROOT).as_posix();assert name not in tracked
  item=m['compressed'][name];raw=path.read_bytes();assert sha(raw)==item['raw_sha256'] and gzip.decompress((out/item['stored']).read_bytes())==raw
  path.unlink();m['removed_verified_generated'].append(dict(path=name,bytes=len(raw)))
 m['all_protected_files_unchanged']=all(sha((ROOT/n).read_bytes())==digest for n,digest in before.items());assert m['all_protected_files_unchanged']
 m['removed_verified_generated_bytes']=sum(v['bytes'] for v in m['removed_verified_generated'])
 (out/'manifest.json').write_bytes((json.dumps(m,indent=2)+'\n').encode())
 print('Protected ROMs unchanged; numbered ROMs:',280,'; removed verified generated bytes:',m['removed_verified_generated_bytes'])

if __name__=='__main__':main()
